import json
R,C=19,16
G=[[4]*C for _ in range(R)]
ones=[(2,2),(4,14),(10,10),(17,9)]
sixes=[(4,4),(6,6),(7,14),(15,2)]
for r,c in ones:G[r][c]=1
for r,c in sixes:G[r][c]=6
pairs=[]
for i,(r1,c1) in enumerate(ones):
 for r2,c2 in ones[i+1:]:
  if r2!=r1 and abs(r2-r1)==abs(c2-c1):
   dr=1 if r2>r1 else -1; dc=1 if c2>c1 else -1
   cells=[(r1+k*dr,c1+k*dc) for k in range(abs(r2-r1)+1)]
   pairs.append(cells)
trigger=[]
for cells in pairs:
 for r,c in cells:
  if (r,c) in sixes: trigger.append((r,c))
  elif G[r][c]==4: G[r][c]=1
# Crossing 6 markers extend a perpendicular diagonal of 6 across the entire grid.
for r,c in sorted(set(trigger)):
 for rr in range(R):
  cc=r+c-rr
  if 0<=cc<C and G[rr][cc]==4:G[rr][cc]=6
assert len(G)==19 and all(len(row)==16 and all(0<=x<=9 for x in row) for row in G)
